import{_ as a,c as t,o as r,aj as n}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse(`{"title":"Baker's Percentage","description":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios.","frontmatter":{"title":"Baker's Percentage","description":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios.","head":[["meta",{"name":"description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["meta",{"property":"og:title","content":"Baker's Percentage"}],["meta",{"property":"og:description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/bakers-percentage.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Baker's Percentage"}],["meta",{"name":"twitter:description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/bakers-percentage.html"}]]},"headers":[],"relativePath":"guides/bakers-percentage.md","filePath":"guides/bakers-percentage.md"}`),i={name:"guides/bakers-percentage.md"};function s(o,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="baker-s-percentage" tabindex="-1">Baker&#39;s Percentage <a class="header-anchor" href="#baker-s-percentage" aria-label="Permalink to “Baker&#39;s Percentage”">​</a></h1><p>Baker&#39;s percentage is shorthand for dough ratios. Flour is the fixed baseline, and everything else is measured against it. That is what makes scaling clean and predictable.</p><ul><li>Flour is always <strong>100%</strong>.</li><li>Water, yeast, salt, and enrichments are percentages of the flour weight.</li></ul><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Understanding the one idea that makes scaling and comparing dough formulas easy.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Flour as the baseline, total percentages over 100%, and ratio-based scaling.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Pair with hydration and the calculator guide to turn the concept into a working formula.</span></div></div><h2 id="the-big-aha-it-won-t-add-up-to-100" tabindex="-1">The Big &quot;Aha&quot;: It Won&#39;t Add Up to 100% <a class="header-anchor" href="#the-big-aha-it-won-t-add-up-to-100" aria-label="Permalink to “The Big &quot;Aha&quot;: It Won&#39;t Add Up to 100%”">​</a></h2><p>This trips people up at first. In baker&#39;s math, <strong>100% is just the flour</strong>, not the total dough.<br> So if you add 65% water + 2% salt + 1% yeast, you get <strong>168% total</strong>. That is normal.<br> Think of the percentages as <strong>relative to flour</strong>, not a pie chart of the whole dough.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>For a dough with:</p><ul><li>500g flour</li><li>325g water</li><li>10g salt</li><li>5g yeast</li></ul><p>The baker&#39;s percentages are:</p><ul><li>Water: 325 ÷ 500 × 100 = <strong>65%</strong></li><li>Salt: 10 ÷ 500 × 100 = <strong>2%</strong></li><li>Yeast: 5 ÷ 500 × 100 = <strong>1%</strong></li></ul><p>That same ratio still works if you scale flour up or down. The percentages stay fixed while the gram weights move.</p><h2 id="why-bakers-love-it" tabindex="-1">Why Bakers Love It <a class="header-anchor" href="#why-bakers-love-it" aria-label="Permalink to “Why Bakers Love It”">​</a></h2><ul><li><strong>Scale fast</strong>: set the ratio, change the flour, and everything follows.</li><li><strong>Compare recipes</strong>: two doughs can be compared by percentage instead of batch size.</li><li><strong>Tune with intent</strong>: change hydration or salt by a point or two and you will feel it.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/calculator-for-recipes.html">Convert Recipes with the Calculator</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div>',18)])])}const p=a(i,[["render",s]]);export{u as __pageData,p as default};
